def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """
    Return True if any two numbers in the list are closer to each other than the given threshold.
    Raises TypeError if inputs are of incorrect type, or ValueError if threshold is negative.
    """
    # Validate inputs
    if not isinstance(numbers, list):
        raise TypeError("numbers must be a list")
    if not isinstance(threshold, (int, float)):
        raise TypeError("threshold must be a numeric value")
    if threshold < 0:
        raise ValueError("threshold must be non-negative")

    # A list with fewer than two elements cannot contain a pair
    if len(numbers) < 2:
        return False

    # Ensure all elements are numeric
    for x in numbers:
        if not isinstance(x, (int, float)):
            raise TypeError("all elements in numbers must be numeric")

    # Sort the numbers to compare only adjacent pairs
    sorted_nums = sorted(numbers)
    for i in range(1, len(sorted_nums)):
        if abs(sorted_nums[i] - sorted_nums[i - 1]) < threshold:
            return True
    return False

def add(a: int, b: int) -> int:
    """Adds two integer numbers together.

    Parameters:
    a (int): The first number to be added.
    b (int): The second number to be added.

    Returns:
    int: The sum of the two numbers.
    """
    if not isinstance(a, int):
        raise TypeError(f"Expected 'a' to be int, got {type(a).__name__}")
    if not isinstance(b, int):
        raise TypeError(f"Expected 'b' to be int, got {type(b).__name__}")
    try:
        return a + b
    except Exception as e:
        raise RuntimeError("Failed to add integers") from e

def max_value_on_paths(N: int, grid_values: list) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    Each value can be collected at most once, even if both paths pass through it.

    Args:
        N (int): The size of the grid (N x N).
        grid_values (List[Tuple[int, int, int]]): A list of tuples where each tuple contains
            the x-coordinate, y-coordinate, and value to be placed on the grid at that position.
            The list is terminated by a tuple with all zeros.

    Returns:
        int: The maximum sum of values collected on the two paths.
    """
    # Input validation
    if not isinstance(N, int) or N <= 0:
        raise ValueError("N must be a positive integer.")
    if not isinstance(grid_values, list):
        raise ValueError("grid_values must be a list of tuples.")
    for item in grid_values:
        if not (isinstance(item, tuple) and len(item) == 3):
            raise ValueError("Each element of grid_values must be a tuple of three integers.")
        if not all(isinstance(v, int) for v in item):
            raise ValueError("All elements of each tuple must be integers.")

    # Build grid (1-indexed)
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    # DP initialization
    NEG_INF = -10**18
    dp = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = grid[1][1]

    # Iterate over steps t = i + j = k + l
    for t in range(3, 2 * N + 1):
        newdp = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        i_min = max(1, t - N)
        i_max = min(N, t - 1)
        for i in range(i_min, i_max + 1):
            j = t - i
            if j < 1 or j > N:
                continue
            for k in range(i_min, i_max + 1):
                l = t - k
                if l < 1 or l > N:
                    continue
                # Value collected at this step
                add = grid[i][j]
                if i != k or j != l:
                    add += grid[k][l]
                # Consider previous positions
                for pi in (i - 1, i):
                    if pi < 1:
                        continue
                    pj = t - 1 - pi
                    if pj < 1 or pj > N:
                        continue
                    for pk in (k - 1, k):
                        if pk < 1:
                            continue
                        pl = t - 1 - pk
                        if pl < 1 or pl > N:
                            continue
                        prev = dp[pi][pk]
                        if prev == NEG_INF:
                            continue
                        if prev + add > newdp[i][k]:
                            newdp[i][k] = prev + add
        dp = newdp

    result = dp[N][N]
    return result if result != NEG_INF else 0

def find_number_combinations():
    """
    Generate all unique combinations of three numbers, each formed from the digits 1 to 9 without repetition,
    such that the second number is twice the first and the third is three times the first.

    Returns:
        list of tuples: A sorted list of tuples, where each tuple contains three integers representing the
                        valid number combinations in ascending order based on the first number.
    """
    result = []
    for a in range(1, 10):
        for b in range(1, 10):
            if b == a:
                continue
            for c in range(1, 10):
                if c == a or c == b:
                    continue
                first = a * 100 + b * 10 + c
                second = first * 2
                third = first * 3

                # Ensure second and third are 3-digit numbers
                if second < 100 or second > 999 or third < 100 or third > 999:
                    continue

                # Helper to check digits of a number
                def valid_digits(num):
                    s = str(num)
                    if '0' in s:
                        return False
                    return len(set(s)) == 3

                if not valid_digits(second) or not valid_digits(third):
                    continue

                result.append((first, second, third))
    return result

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    try:
        # Basic type checks
        if not isinstance(encoded, str) or not isinstance(original, str) or not isinstance(message, str):
            return "Failed"
        # Length must match
        if len(encoded) != len(original):
            return "Failed"
        # Build mapping and reverse mapping
        mapping = {}
        rev_mapping = {}
        for e_char, o_char in zip(encoded, original):
            # Ensure characters are single letters
            if len(e_char) != 1 or len(o_char) != 1:
                return "Failed"
            # Check consistency
            if e_char in mapping:
                if mapping[e_char] != o_char:
                    return "Failed"
            else:
                mapping[e_char] = o_char
            if o_char in rev_mapping:
                if rev_mapping[o_char] != e_char:
                    return "Failed"
            else:
                rev_mapping[o_char] = e_char
        # Ensure all 26 uppercase letters are represented
        alphabet = set("ABCDEFGHIJKLMNOPQRSTUVWXYZ")
        if set(mapping.keys()) != alphabet or set(mapping.values()) != alphabet:
            return "Failed"
        # Decode message
        decoded_chars = []
        for ch in message:
            if ch not in mapping:
                return "Failed"
            decoded_chars.append(mapping[ch])
        return "".join(decoded_chars)
    except Exception:
        return "Failed"

